it("should handle cells at negative coordinates", () => {
  const result = nextGeneration([
    [-5, -5],
    [-5, -4],
    [-5, -3],
  ]);
  expect(result).toHaveLength(3);
  expect(result).toContainEqual([-6, -4]);
  expect(result).toContainEqual([-5, -4]);
  expect(result).toContainEqual([-4, -4]);
});
